package com.mohymods.kingdomsmp.equipment;
import com.mohymods.kingdomsmp.building.ConstructionService;
import com.mohymods.kingdomsmp.economy.CommerceService;
import com.mohymods.kingdomsmp.network.CommerceView;
import com.mohymods.kingdomsmp.profession.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerPlayer;
import java.io.IOException;
import java.util.*;
/** Local, rank-gated canonical shop. No free Master completion item and no global usage ban. */
public final class FarmerGearService {
 public record Quote(UUID nonce,long revision,FarmerGear gear,long base,long price,long issued,String text){ }
 private static final Map<ServerPlayer,Quote> QUOTES=new WeakHashMap<>();
 private FarmerGearService(){ }
 public static void close(ServerPlayer p){QUOTES.remove(p);}
 private static void requireCounter(ServerPlayer p,FarmerGear gear){CommerceService.requireResidentCounter(p);var roster=CommerceService.store(p.server).professions(p.getUUID());if(!roster.perksEligible(Profession.FARMER,gear.rank(),FarmerQuests.catalog()))throw new IllegalStateException("Purchase requires active Farmer "+gear.rank()+". Inactive progress is retained but grants no shop access.");if(!ProfessionService.available(p,Profession.FARMER))throw new IllegalStateException("Maintain the Farmer's House before purchasing equipment.");boolean near=ConstructionService.store(p.server).projects().stream().filter(v->v.blueprint().toString().equals(Profession.FARMER.buildingId())).anyMatch(v->{var e=p.serverLevel().getEntity(v.npc());return e instanceof com.mohymods.kingdomsmp.npc.ReeveEntity npc&&ConstructionService.registeredReeve(npc)&&p.distanceToSqr(npc)<=64&&p.hasLineOfSight(npc);});if(!near)throw new IllegalStateException("Buy Farmer equipment at the assigned Farmer within eight blocks and clear sight.");}
 public static Quote review(ServerPlayer p,String id)throws IOException{var gear=FarmerGear.byId(id);requireCounter(p,gear);var store=CommerceService.store(p.server);CommerceService.verifyReceipt(p,store);long base=FarmerGearRules.get(p.server).base(gear),price=gear.price(base,store.equipmentPurchases(p.getUUID(),id));if(store.balance(p.getUUID())<price)throw new IllegalStateException("Equipment costs "+price+" coins. No funds or purchase count changed.");String text="Buy "+gear.title()+" for exactly "+price+" coins into recoverable private item mail. Fortune "+gear.fortune()+"; up to "+(gear.radius()*2+1)+"×"+(gear.radius()*2+1)+" mature crops harvested and replanted with real supplied seeds through normal protection checks. Sneak for one crop. Work is bounded per tick. "+(gear.master()?"Your next same-item purchase costs base ×1.5 compounded; counts are personal and increase only on successful purchases. ":"")+"Trading and use by other players are allowed. Claim your equipment from the Mailbox after purchase.";var q=new Quote(UUID.randomUUID(),store.revision(),gear,base,price,System.nanoTime(),text);QUOTES.put(p,q);return q;}
 public static String confirm(ServerPlayer p,UUID nonce)throws IOException{var q=QUOTES.remove(p);var store=CommerceService.store(p.server);CommerceService.verifyReceipt(p,store);if(q==null||!q.nonce().equals(nonce)||q.revision()!=store.revision()||System.nanoTime()-q.issued()>30_000_000_000L)throw new IllegalStateException("Equipment review expired or funds/profession changed; review again.");requireCounter(p,q.gear());if(FarmerGearRules.get(p.server).base(q.gear())!=q.base()||q.gear().price(q.base(),store.equipmentPurchases(p.getUUID(),q.gear().id()))!=q.price())throw new IllegalStateException("Exact equipment price changed; review again.");store.buyFarmerGear(q.nonce(),p.getUUID(),q.gear().id(),q.base(),(CompoundTag)FarmerGearItems.stack(p,q.gear()).save(p.registryAccess()));return q.gear().title()+" purchased once. Claim it in your private Mailbox; the saved purchase count and exact price are persistent.";}
 public static List<CommerceView.Entry> entries(ServerPlayer p){var store=CommerceService.store(p.server);var roster=store.professions(p.getUUID());List<CommerceView.Entry> rows=new ArrayList<>();for(var gear:FarmerGear.values()){long price;try{price=gear.price(FarmerGearRules.get(p.server).base(gear),store.equipmentPurchases(p.getUUID(),gear.id()));}catch(IllegalStateException limit){rows.add(new CommerceView.Entry("gear:"+gear.id(),gear.title(),"Further price exceeds the supported coin balance; no purchase is available.",0,"LOCKED"));continue;}boolean allowed=roster.perksEligible(Profession.FARMER,gear.rank(),FarmerQuests.catalog())&&ProfessionService.available(p,Profession.FARMER);rows.add(new CommerceView.Entry("gear:"+gear.id(),gear.title(),"Purchase at the Farmer: active "+ProfessionService.rankName(gear.rank())+" required. Fortune "+gear.fortune()+", "+(gear.radius()*2+1)+"×"+(gear.radius()*2+1)+" real harvest/replant; supply seeds. Sneak for one crop. Recoverable private delivery. "+(gear.master()?"Personal repeat purchases increase by 50%.":"Useful Journeyman equipment.")+" May be traded and used by others.",price,allowed?"EQUIPMENT":"LOCKED"));}return List.copyOf(rows);}
}
